-- Native monitoring and token-free session administration. Idempotent; no business data changes.
SET NAMES utf8mb4;
UPDATE system_menu SET name='数据监控',permission='infra:druid:query' WHERE id=15 AND component='infra/druid/index';
UPDATE system_menu SET name='服务监控',permission='infra:server:query' WHERE id=16 AND component='infra/server/index';
INSERT INTO system_menu (id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,deleted) VALUES (970120,'数据监控查询','infra:druid:query',3,1,15,'','ep:connection','','',0,b'1',b'1',b'1','1','1',b'0') ON DUPLICATE KEY UPDATE name=VALUES(name),permission=VALUES(permission),parent_id=VALUES(parent_id),path=VALUES(path),component=VALUES(component),component_name=VALUES(component_name),status=0,deleted=b'0';
UPDATE system_tenant_package SET menu_ids=JSON_ARRAY_APPEND(menu_ids,'$',970120) WHERE id IN (SELECT package_id FROM system_tenant WHERE id=1 AND deleted=b'0') AND JSON_VALID(menu_ids) AND NOT JSON_CONTAINS(menu_ids,CAST('970120' AS JSON));
