INSERT INTO system_role_menu (role_id,menu_id,tenant_id,creator,updater) SELECT r.id,m.id,r.tenant_id,'1','1' FROM system_role r JOIN system_menu m ON m.id BETWEEN 970120 AND 970124 WHERE r.tenant_id=1 AND r.code IN ('super_admin','tenant_admin') AND r.deleted=b'0' AND NOT EXISTS (SELECT 1 FROM system_role_menu rm WHERE rm.role_id=r.id AND rm.menu_id=m.id AND rm.tenant_id=r.tenant_id AND rm.deleted=b'0');
